  "decisions": [
    {
      "benefit": "pension_credit",
      "decision": "not_eligible",
      "weekly_amount": 0,
      "clause_ids": ["PC-1", "PC-2", "PC-4"],
      "record_ids": ["persons:QQ101184A", "PEN-00033"],
      "reason": "Beryl Young (dob 1965-02-10) is 61 as of the assessment date 2026-10-27. Under the simplification, people born on or after 6 April 1960 reach State Pension age at 67. She has not reached State Pension age, which is a mandatory condition under PC-1. Therefore she is not eligible for Pension Credit Guarantee Credit."
    },
    {
      "benefit": "attendance_allowance",
      "decision": "not_eligible",
      "weekly_amount": 0,
      "clause_ids": ["AA-1"],
      "record_ids": ["persons:QQ101184A", "note:HH-029.txt"],
      "reason": "Attendance Allowance requires the claimant to have reached State Pension age (AA-1). Beryl is 61, below the State Pension age of 67. Additionally, the caseworker note records that she manages personal care independently and reported no difficulties, so the disability condition (AA-2) is also not met."
    },
    {
      "benefit": "council_tax_reduction",
      "decision": "not_eligible",
      "weekly_amount": 0,
      "clause_ids": ["CTR-2"],
      "record_ids": ["persons:QQ101184A", "CT-70364"],
      "reason": "The pensioner Council Tax Reduction scheme applies only to people who have reached State Pension age (CTR-2). Beryl is 61 and has not reached State Pension age (67). Therefore she is not eligible under the pensioner scheme. (No working-age scheme is covered by the provided policy.)"
    },
    {
      "benefit": "warm_home_discount",
      "decision": "not_eligible",
      "weekly_amount": 0,
      "clause_ids": ["WHD-2", "WHD-3"],
      "record_ids": ["TEN-4128", "PEN-00033", "CT-70364"],
      "reason": "The Warm Home Discount qualifying date is 23 August 2026. Eligibility requires that the claimant or partner receives a qualifying means-tested benefit (Pension Credit, Housing Benefit, Universal Credit, or income-related ESA) on that date (WHD-2). Beryl does not receive Pension Credit (she is below State Pension age) and there is no record of her receiving any of the other qualifying benefits. Although her name is on the electricity bill (WHD-3 satisfied per TEN-4128), the benefit condition is not met."
    }
  ]
}
